const items = $input.all();
let articles = [];
items.forEach(item => {
  const data = item.json;
  if (data.articles && Array.isArray(data.articles)) {
    articles = articles.concat(data.articles);
  }
});
const summaries = articles.slice(0, 15).map((a, i) => {
  return `[${i+1}] Title: ${a.title || ''}\nSource: ${a.source?.name || ''}\nDescription: ${a.description || ''}\nURL: ${a.url || ''}`;
}).join('\n\n');
return [{ json: { articleSummaries: summaries, articleCount: articles.length, date: new Date().toISOString().split('T')[0] } }];

const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { subject_line: 'Daily News Digest', articles: [], top_story: {}, trend_watch: aiResponse, quote_of_day: '' };
}

const articlesHtml = (parsed.articles || []).map(a => {
  const badge = a.importance === 'High' ? '🔴' : a.importance === 'Medium' ? '🟡' : '🟢';
  return `<div style="margin-bottom:15px;"><strong>${badge} [${a.category}] ${a.title}</strong><br>${a.summary}<br><a href="${a.url}">Read more →</a></div>`;
}).join('');

const topStory = parsed.top_story || {};

return [{
  json: {
    date: items[0].json.date || new Date().toISOString().split('T')[0],
    subjectLine: parsed.subject_line || 'Daily News Digest',
    topStoryTitle: topStory.title || '',
    topStorySummary: topStory.summary || '',
    topStoryWhy: topStory.why_it_matters || '',
    articlesHtml,
    articleCount: (parsed.articles || []).length,
    trendWatch: parsed.trend_watch || '',
    quoteOfDay: parsed.quote_of_day || ''
  }
}];
